package com.crm.invoice.entity;import jakarta.persistence.*;import lombok.Data;
@Entity @Table(name="invoice_presentations") @Data public class InvoicePresentation {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(nullable=false,length=100) private String name;@Column(nullable=false,length=255) private String header;@Column(nullable=false,length=1000) private String company;@Column(nullable=false,length=1000) private String footer;@Column(nullable=false,length=1000) private String mentions;@Column(nullable=false,length=20) private String layout;@Column(nullable=false) private boolean active=true;@Column(nullable=false) private boolean used;@Lob @Column(columnDefinition="LONGBLOB") private byte[] logo;}
